package co.edu.icesi.pdg.mte.governance;
import co.edu.icesi.pdg.mte.audit.*;
import com.fasterxml.jackson.databind.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import static co.edu.icesi.pdg.mte.governance.GovernanceV2Service.*;

@Service @Transactional
public class CycleClosureV2Service {
    public record Write(List<Long> reportIds,String achievements,String causes,String learnings,String continuity,Boolean confirmed) {}
    public record Page(List<Map<String,Object>> items,long totalElements,long totalPages,int currentPage,int pageSize) {}
    private final JdbcTemplate jdbc;private final TrackingV2Service tracking;private final ObjectMapper mapper;private final AuditService audit;private final StrategyV2Service strategy;
    public CycleClosureV2Service(JdbcTemplate jdbc,TrackingV2Service tracking,ObjectMapper mapper,AuditService audit,StrategyV2Service strategy){this.jdbc=jdbc;this.tracking=tracking;this.mapper=mapper;this.audit=audit;this.strategy=strategy;}
    private boolean role(long actor,String role){return jdbc.queryForObject("SELECT COUNT(*) FROM user_role WHERE professor_id=? AND role_name=? AND started_at<=CURRENT_TIMESTAMP AND ended_at IS NULL",Long.class,actor,role)>0;}
    private TrackingV2Service.Actor reader(){var actor=tracking.actor();if(!actor.admin()&&!role(actor.id(),"RECTOR")&&!role(actor.id(),"AUDITOR"))throw error(HttpStatus.FORBIDDEN,"FORBIDDEN");return actor;}
    private Map<String,Object> cycle(long id){return tracking.jsonRows("SELECT id,name,status,version FROM strategic_cycle WHERE id=?",id).stream().findFirst().orElseThrow(()->error(HttpStatus.NOT_FOUND,"CYCLE_NOT_FOUND"));}
    private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private JsonNode parse(Object value){try{var node=mapper.readTree(value instanceof byte[] bytes?new String(bytes,StandardCharsets.UTF_8):String.valueOf(value));return node.isTextual()?mapper.readTree(node.asText()):node;}catch(Exception e){throw error(HttpStatus.CONFLICT,"SNAPSHOT_UNAVAILABLE");}}
    private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json(value).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private List<Map<String,Object>> live(long cycle){
        return tracking.jsonRows("SELECT k.id,k.name,k.version,k.status,k.active,k.base_value AS \"baseValue\",k.target_value AS \"targetValue\",k.metric_definition_id AS \"metricDefinitionId\",d.school_id AS \"schoolId\",m.name AS \"metricName\",u.name AS \"unitName\",(SELECT measured_value FROM kr_measurement e WHERE e.key_result_id=k.id AND e.status='ACTIVE' AND e.observed_at<=CURRENT_TIMESTAMP ORDER BY e.observed_at DESC,e.id DESC LIMIT 1) AS \"measuredValue\",(SELECT observed_at FROM kr_measurement e WHERE e.key_result_id=k.id AND e.status='ACTIVE' AND e.observed_at<=CURRENT_TIMESTAMP ORDER BY e.observed_at DESC,e.id DESC LIMIT 1) AS \"observedAt\",(SELECT progress_percent FROM kr_progress_entry e WHERE e.key_result_id=k.id ORDER BY e.declared_at DESC,e.id DESC LIMIT 1) AS \"manualProgress\",(SELECT declared_at FROM kr_progress_entry e WHERE e.key_result_id=k.id ORDER BY e.declared_at DESC,e.id DESC LIMIT 1) AS \"declaredAt\" FROM key_result k LEFT JOIN objective o ON o.id=k.objective_id LEFT JOIN kr_assignment a ON a.key_result_id=k.id AND a.ended_at IS NULL LEFT JOIN professor p ON p.id=a.professor_id LEFT JOIN department d ON d.id=COALESCE(o.department_id,p.department_id) LEFT JOIN metric_definition m ON m.id=k.metric_definition_id LEFT JOIN unit_of_measure u ON u.id=m.unit_of_measure_id WHERE k.strategic_cycle_id=? ORDER BY k.id",cycle);
    }
    private List<Map<String,Object>> reports(long cycle,List<Map<String,Object>> krs){
        var result=new ArrayList<Map<String,Object>>();var schools=krs.stream().filter(k->!closed(k)||krClosure(((Number)k.get("id")).longValue())==null).map(k->k.get("schoolId")).filter(Objects::nonNull).distinct().toList();
        for(var school:schools){var rows=tracking.jsonRows("SELECT r.id,r.report_version AS \"reportVersion\",r.status,r.cut_id AS \"cutId\",r.final_review_id AS \"reviewId\",c.school_id AS \"schoolId\",s.name AS \"schoolName\",c.status AS \"cutStatus\",v.status AS \"reviewStatus\",v.report_id AS \"reviewReportId\",v.report_version AS \"reviewReportVersion\",v.reviewed_at AS \"reviewedAt\",r.finished_at AS \"finishedAt\",CAST(r.content_snapshot AS VARCHAR) AS content FROM monitoring_cut c JOIN school s ON s.id=c.school_id LEFT JOIN school_final_report r ON r.cut_id=c.id AND r.report_version=(SELECT MAX(x.report_version) FROM school_final_report x WHERE x.cut_id=c.id) LEFT JOIN rector_review v ON v.id=r.final_review_id WHERE c.cycle_id=? AND c.school_id=? AND c.id=(SELECT MAX(x.id) FROM monitoring_cut x WHERE x.cycle_id=c.cycle_id AND x.school_id=c.school_id)",cycle,school);
            if(rows.isEmpty())result.add(new LinkedHashMap<>(Map.of("schoolId",school,"status","MISSING")));else result.add(rows.get(0));
        }
        for(var kr:krs){if(!closed(kr))continue;var archived=krClosure(((Number)kr.get("id")).longValue());if(archived==null)continue;long report=((Number)archived.get("reportId")).longValue();if(result.stream().noneMatch(r->Objects.equals(r.get("id"),report)))result.add(report(report));}
        return result;
    }
    private boolean closed(Map<String,Object> kr){return Set.of("CERRADO","CLOSED").contains(String.valueOf(kr.get("status")));}
    private Map<String,Object> report(long id){return tracking.jsonRows("SELECT r.id,r.report_version AS \"reportVersion\",r.status,r.cut_id AS \"cutId\",r.final_review_id AS \"reviewId\",c.school_id AS \"schoolId\",s.name AS \"schoolName\",c.status AS \"cutStatus\",v.status AS \"reviewStatus\",v.report_id AS \"reviewReportId\",v.report_version AS \"reviewReportVersion\",v.reviewed_at AS \"reviewedAt\",r.finished_at AS \"finishedAt\",CAST(r.content_snapshot AS VARCHAR) AS content FROM school_final_report r JOIN monitoring_cut c ON c.id=r.cut_id JOIN school s ON s.id=c.school_id LEFT JOIN rector_review v ON v.id=r.final_review_id WHERE r.id=?",id).stream().findFirst().orElseThrow(()->error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED"));}
    private void reviewed(Map<String,Object> report){if(report.get("id")==null||!"FIN".equals(report.get("cutStatus"))||!"APPROVED".equals(report.get("status"))||!"APPROVED".equals(report.get("reviewStatus"))||!Objects.equals(report.get("id"),report.get("reviewReportId"))||!same(mapper.valueToTree(report.get("reviewReportVersion")),report.get("reportVersion"))||report.get("finishedAt")==null)throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");}
    private Map<String,Object> krClosure(long id){var rows=tracking.jsonRows("SELECT id,key_result_id AS \"keyResultId\",cycle_id AS \"cycleId\",report_id AS \"reportId\",rector_review_id AS \"reviewId\",actor_id AS \"actorId\",reason,closed_version AS \"closedVersion\",closed_at AS \"closedAt\",CAST(definition_snapshot AS VARCHAR) AS definition,CAST(capture_snapshot AS VARCHAR) AS capture FROM key_result_closure WHERE key_result_id=?",id);if(rows.isEmpty())return null;var row=rows.get(0);row.put("definition",parse(row.get("definition")));row.put("capture",parse(row.get("capture")));return row;}
    private Map<String,Object> scopedDefinition(long id,TrackingV2Service.Actor actor){if(!actor.admin()&&!role(actor.id(),"RECTOR")&&!role(actor.id(),"AUDITOR"))tracking.scopedKr(id,actor,false);if(jdbc.queryForObject("SELECT COUNT(*) FROM key_result WHERE id=?",Long.class,id)==0)throw error(HttpStatus.NOT_FOUND,"OUT_OF_SCOPE");return strategy.definition(id);}
    private void currentCapture(JsonNode saved,Map<String,Object> kr,boolean individuallyClosed){
        for(String field:List.of("id","name","version","baseValue","targetValue","metricDefinitionId","metricName","unitName","measuredValue","observedAt","manualProgress","declaredAt")){
            Object current=kr.get(field);if(individuallyClosed&&field.equals("version"))current=((Number)current).longValue()-1;
            if(!same(saved.path(field),current))throw error(HttpStatus.CONFLICT,"FINAL_SNAPSHOT_STALE");
        }
    }
    private JsonNode capture(Map<String,Object> report,long kr){var cut=parse(report.get("content")).path("cutReport");var records=cut.path("lifecycleInventoryCaptured").asBoolean()?cut.path("lifecycleInventory"):cut.path("keyResults");if(!records.isArray())throw error(HttpStatus.CONFLICT,"SNAPSHOT_UNAVAILABLE");JsonNode found=null;for(var record:records)if(record.path("id").asLong()==kr){if(found!=null)throw error(HttpStatus.CONFLICT,"SNAPSHOT_UNAVAILABLE");found=record;}if(found==null)throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");return found;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> krContext(long id){var actor=tracking.actor();var definition=scopedDefinition(id,actor);if(definition.get("strategicCycleId")==null)throw error(HttpStatus.CONFLICT,"INVALID_CYCLE");var cycle=cycle(((Number)definition.get("strategicCycleId")).longValue());var archived=krClosure(id);var reports=new ArrayList<Map<String,Object>>();if(archived!=null){reports.add(report(((Number)archived.get("reportId")).longValue()));}else if(!"CLOSED".equals(cycle.get("status"))){var kr=live(((Number)cycle.get("id")).longValue()).stream().filter(k->((Number)k.get("id")).longValue()==id).findFirst();if(kr.isPresent())reports.addAll(reports(((Number)cycle.get("id")).longValue(),List.of(kr.get())));}
        reports.forEach(r->r.remove("content"));var result=new LinkedHashMap<String,Object>();result.put("keyResult",definition);result.put("closure",archived);result.put("reports",reports);result.put("canClose",(actor.admin()||actor.manager()||role(actor.id(),"RECTOR"))&&"ACTIVE".equals(definition.get("status"))&&!"CLOSED".equals(cycle.get("status")));return result;
    }
    public Map<String,Object> closeKr(long id,StrategyV2Service.StatusWrite request,long expected,String key){
        var actor=tracking.actor();scopedDefinition(id,actor);if(!actor.admin()&&!actor.manager()&&!role(actor.id(),"RECTOR"))throw error(HttpStatus.FORBIDDEN,"FORBIDDEN");if(!actor.admin()&&!role(actor.id(),"RECTOR"))tracking.scopedKr(id,actor,false);
        required(request.reason(),"REASON_REQUIRED");if(request.reason().length()>10000)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_REQUEST");if(!Boolean.TRUE.equals(request.confirmed()))throw error(HttpStatus.UNPROCESSABLE_ENTITY,"CONFIRMATION_REQUIRED");if(request.reportId()==null)throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");if(key==null||key.isBlank()||key.length()>128)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"IDEMPOTENCY_KEY_REQUIRED");
        var definition=strategy.definition(id);if(definition.get("strategicCycleId")==null)throw error(HttpStatus.CONFLICT,"INVALID_CYCLE");long cycleId=((Number)definition.get("strategicCycleId")).longValue();jdbc.queryForList("SELECT id FROM strategic_cycle WHERE id=? FOR UPDATE",cycleId);String fingerprint=hash(Map.of("request",request,"version",expected));var existing=jdbc.queryForList("SELECT actor_id,command_key,request_fingerprint FROM key_result_closure WHERE key_result_id=?",id);if(!existing.isEmpty()){var old=existing.get(0);if(Objects.equals(old.get("actor_id"),actor.id())&&key.equals(old.get("command_key"))&&fingerprint.equals(old.get("request_fingerprint")))return krClosure(id);throw error(HttpStatus.CONFLICT,"KR_ALREADY_CLOSED");}
        if("CLOSED".equals(cycle(cycleId).get("status")))throw error(HttpStatus.CONFLICT,"CYCLE_CLOSED");jdbc.queryForList("SELECT id FROM monitoring_cut WHERE cycle_id=? ORDER BY id FOR UPDATE",cycleId);jdbc.queryForList("SELECT id FROM key_result WHERE id=? FOR UPDATE",id);
        definition=scopedDefinition(id,actor);if(((Number)definition.get("version")).longValue()!=expected)throw error(HttpStatus.CONFLICT,"VERSION_CONFLICT");var kr=live(cycleId).stream().filter(k->((Number)k.get("id")).longValue()==id).findFirst().orElseThrow(()->error(HttpStatus.CONFLICT,"INACTIVE_RESOURCE"));if(!Set.of("ACTIVE","ACTIVO").contains(String.valueOf(kr.get("status"))))throw error(HttpStatus.CONFLICT,"INVALID_TRANSITION");
        var sources=reports(cycleId,List.of(kr));if(sources.size()!=1||!Objects.equals(sources.get(0).get("id"),request.reportId()))throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");var source=sources.get(0);reviewed(source);var saved=capture(source,id);currentCapture(saved,kr,false);var frozen=finalDefinition(id,saved);var after=new LinkedHashMap<>(frozen);after.put("status","CLOSED");after.put("version",expected+1);
        jdbc.update("INSERT INTO key_result_closure(key_result_id,cycle_id,report_id,rector_review_id,actor_id,reason,command_key,request_fingerprint,closed_version,definition_snapshot,capture_snapshot) VALUES(?,?,?,?,?,?,?,?,?,CAST(? AS JSONB),CAST(? AS JSONB))",id,cycleId,request.reportId(),source.get("reviewId"),actor.id(),request.reason().trim(),key,fingerprint,expected+1,json(frozen),json(saved));jdbc.update("UPDATE key_result SET status='CERRADO',version=version+1 WHERE id=?",id);jdbc.update("INSERT INTO kr_version(key_result_id,version,snapshot,reason,actor_id) VALUES(?,?,CAST(? AS JSONB),?,?)",id,expected+1,json(Map.of("before",frozen,"after",after,"reportId",request.reportId())),request.reason().trim(),actor.id());var result=krClosure(id);audit.record(AuditAction.STATUS_CHANGE,"KEY_RESULT",id,"Cierre individual KR: "+request.reason().trim(),frozen,result);return result;
    }
    private Map<String,Object> closure(long cycle){
        var rows=tracking.jsonRows("SELECT id,cycle_id AS \"cycleId\",closure_status AS status,closed_by AS \"closedBy\",closed_at AS \"closedAt\",retrospective_achievements AS achievements,retrospective_causes AS causes,retrospective_learnings AS learnings,retrospective_continuity AS continuity,version,CAST(reports_snapshot AS VARCHAR) AS reports FROM cycle_closure WHERE cycle_id=?",cycle);
        if(rows.isEmpty())return null;var result=rows.get(0);if(result.get("reports")!=null)result.put("reports",parse(result.get("reports")));return result;
    }
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Map<String,Object> context(long id){var actor=reader();var cycle=cycle(id);var result=new LinkedHashMap<String,Object>();result.put("cycle",cycle);result.put("canClose",role(actor.id(),"RECTOR")&&!"CLOSED".equals(cycle.get("status")));var existing=closure(id);result.put("closure",existing);List<Map<String,Object>> reports=existing==null?reports(id,live(id)):mapper.convertValue(existing.get("reports"),new com.fasterxml.jackson.core.type.TypeReference<List<Map<String,Object>>>(){});reports.forEach(r->r.remove("content"));result.put("reports",reports);return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public Page snapshots(long id,int page,int size){reader();cycle(id);if(page<0||page>1000000||size<1||size>100)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_PAGINATION");
        long total=jdbc.queryForObject("SELECT COUNT(*) FROM cycle_closure_snapshot s JOIN cycle_closure c ON c.id=s.cycle_closure_id WHERE c.cycle_id=?",Long.class,id);var items=tracking.jsonRows("SELECT s.id,s.key_result_id AS \"keyResultId\",s.kr_name AS name,s.final_measured_value AS \"measuredValue\",s.final_manual_progress AS \"manualProgress\",s.final_status AS status,s.source_report_id AS \"sourceReportId\",s.source_review_id AS \"sourceReviewId\",s.closure_origin AS \"closureOrigin\",CAST(s.definition_snapshot AS VARCHAR) AS definition FROM cycle_closure_snapshot s JOIN cycle_closure c ON c.id=s.cycle_closure_id WHERE c.cycle_id=? ORDER BY s.key_result_id LIMIT ? OFFSET ?",id,size,(long)page*size);items.forEach(r->{if(r.get("definition")!=null)r.put("definition",parse(r.get("definition")));});return new Page(items,total,(total+size-1)/size,page,size);
    }
    private boolean same(JsonNode saved,Object current){if(current==null)return saved.isMissingNode()||saved.isNull();if(saved.isNumber()&&current instanceof Number)return saved.decimalValue().compareTo(new BigDecimal(current.toString()))==0;return saved.asText().equals(String.valueOf(current));}
    private Map<String,Object> finalDefinition(long id,JsonNode saved){var definition=new LinkedHashMap<>(strategy.definition(id));definition.putAll(mapper.convertValue(saved,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){}));definition.put("status",Boolean.FALSE.equals(definition.get("active"))?"INACTIVE":Set.of("CERRADO","CLOSED").contains(saved.path("status").asText())?"CLOSED":"ACTIVE");return definition;}
    public Map<String,Object> close(long id,Write r,long expected,String key){
        var actor=reader();if(!role(actor.id(),"RECTOR"))throw error(HttpStatus.FORBIDDEN,"FORBIDDEN");
        if(key==null||key.isBlank()||key.length()>128)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"IDEMPOTENCY_KEY_REQUIRED");
        if(r.reportIds()==null||r.reportIds().isEmpty()||r.reportIds().stream().anyMatch(Objects::isNull)||new HashSet<>(r.reportIds()).size()!=r.reportIds().size())throw error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_REPORT_SELECTION");
        for(String text:new String[]{r.achievements(),r.causes(),r.learnings(),r.continuity()}){required(text,"RETROSPECTIVE_REQUIRED");if(text.length()>10000)throw error(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_REQUEST");}if(!Boolean.TRUE.equals(r.confirmed()))throw error(HttpStatus.UNPROCESSABLE_ENTITY,"CONFIRMATION_REQUIRED");
        jdbc.queryForList("SELECT id FROM strategic_cycle WHERE id=? FOR UPDATE",id);var before=cycle(id);String fingerprint=hash(Map.of("request",r,"version",expected));
        var existing=jdbc.queryForList("SELECT actor_id,command_key,request_fingerprint FROM cycle_closure WHERE cycle_id=?",id);if(!existing.isEmpty()){var old=existing.get(0);if(Objects.equals(old.get("actor_id"),actor.id())&&key.equals(old.get("command_key"))&&fingerprint.equals(old.get("request_fingerprint")))return closure(id);throw error(HttpStatus.CONFLICT,"CYCLE_ALREADY_CLOSED");}
        if(((Number)before.get("version")).longValue()!=expected)throw error(HttpStatus.CONFLICT,"VERSION_CONFLICT");if("CLOSED".equals(before.get("status")))throw error(HttpStatus.CONFLICT,"CYCLE_CLOSED");
        jdbc.queryForList("SELECT id FROM monitoring_cut WHERE cycle_id=? ORDER BY id FOR UPDATE",id);jdbc.queryForList("SELECT id FROM key_result WHERE strategic_cycle_id=? ORDER BY id FOR UPDATE",id);var krs=live(id);if(krs.isEmpty()||krs.stream().anyMatch(k->k.get("schoolId")==null||(Boolean.TRUE.equals(k.get("active"))&&!Set.of("ACTIVO","ACTIVE","CERRADO","CLOSED").contains(String.valueOf(k.get("status"))))))throw error(HttpStatus.CONFLICT,"CYCLE_SCOPE_INCOMPLETE");
        var reports=reports(id,krs);var selected=new HashSet<>(r.reportIds());var captured=new HashMap<Long,JsonNode>();var sourcesByKr=new HashMap<Long,Map<String,Object>>();var archived=new HashMap<Long,Map<String,Object>>();
        for(var report:reports){reviewed(report);if(!selected.remove(((Number)report.get("id")).longValue()))throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");}
        if(!selected.isEmpty())throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");
        for(var kr:krs){long krId=((Number)kr.get("id")).longValue();Map<String,Object> source;
            var old=closed(kr)?krClosure(krId):null;
            if(old!=null){if(!Objects.equals(old.get("closedVersion"),kr.get("version")))throw error(HttpStatus.CONFLICT,"KR_CLOSURE_UNAVAILABLE");archived.put(krId,old);source=reports.stream().filter(v->Objects.equals(v.get("id"),old.get("reportId"))).findFirst().orElseThrow(()->error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED"));if(!Objects.equals(source.get("reviewId"),old.get("reviewId")))throw error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED");}
            else source=reports.stream().filter(v->Objects.equals(v.get("schoolId"),kr.get("schoolId"))).findFirst().orElseThrow(()->error(HttpStatus.CONFLICT,"FINAL_REVIEW_REQUIRED"));
            var saved=capture(source,krId);if(old!=null&&!saved.equals(old.get("capture")))throw error(HttpStatus.CONFLICT,"FINAL_SNAPSHOT_STALE");currentCapture(saved,kr,old!=null);
            if(old==null&&(!Boolean.TRUE.equals(kr.get("active"))||closed(kr))){if(saved.path("active").isMissingNode()||!same(saved.path("active"),kr.get("active"))||!same(saved.path("status"),kr.get("status")))throw error(HttpStatus.CONFLICT,"LIFECYCLE_SNAPSHOT_REQUIRED");}
            captured.put(krId,saved);sourcesByKr.put(krId,source);
        }
        var source=reports.stream().map(report->{var metadata=new LinkedHashMap<>(report);metadata.remove("content");return metadata;}).toList();var values=new HashMap<String,Object>();values.put("cycle_id",id);values.put("rector_review_id",reports.get(0).get("reviewId"));values.put("closed_by",actor.name());values.put("retrospective_achievements",r.achievements().trim());values.put("retrospective_causes",r.causes().trim());values.put("retrospective_learnings",r.learnings().trim());values.put("retrospective_continuity",r.continuity().trim());
        long closure=tracking.insert("cycle_closure",values);jdbc.update("UPDATE cycle_closure SET actor_id=?,command_key=?,request_fingerprint=?,reports_snapshot=CAST(? AS JSONB) WHERE id=?",actor.id(),key,fingerprint,json(source),closure);
        for(var kr:krs){long krId=((Number)kr.get("id")).longValue();var saved=captured.get(krId);var definition=archived.containsKey(krId)?mapper.convertValue(archived.get(krId).get("definition"),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){}):finalDefinition(krId,saved);var closed=new LinkedHashMap<>(definition);closed.put("status","CLOSED");closed.put("version",((Number)kr.get("version")).longValue()+1);var snapshotValues=new HashMap<String,Object>();snapshotValues.put("cycle_closure_id",closure);snapshotValues.put("key_result_id",krId);snapshotValues.put("kr_name",kr.get("name"));snapshotValues.put("final_status",Boolean.TRUE.equals(kr.get("active"))?"CLOSED":"INACTIVE");snapshotValues.put("source_report_id",sourcesByKr.get(krId).get("id"));snapshotValues.put("source_review_id",sourcesByKr.get(krId).get("reviewId"));snapshotValues.put("closure_origin",archived.containsKey(krId)?"INDIVIDUAL_CLOSURE":(!Boolean.TRUE.equals(kr.get("active"))||closed(kr))?"LIFECYCLE_RECONCILIATION":"FINAL_REVIEW");if(kr.get("measuredValue")!=null)snapshotValues.put("final_measured_value",kr.get("measuredValue"));if(kr.get("manualProgress")!=null)snapshotValues.put("final_manual_progress",kr.get("manualProgress"));long snapshot=tracking.insert("cycle_closure_snapshot",snapshotValues);jdbc.update("UPDATE cycle_closure_snapshot SET definition_snapshot=CAST(? AS JSONB) WHERE id=?",json(definition),snapshot);
            if(!Boolean.TRUE.equals(kr.get("active"))||closed(kr))continue;
            jdbc.update("UPDATE key_result SET status='CERRADO',version=version+1 WHERE id=?",krId);jdbc.update("INSERT INTO kr_version(key_result_id,version,snapshot,reason,actor_id) VALUES(?,?,CAST(? AS JSONB),?,?)",krId,((Number)kr.get("version")).longValue()+1,json(Map.of("before",definition,"after",closed,"cycleClosureId",closure)),"Cierre de ciclo con revisión rectoral",actor.id());audit.record(AuditAction.STATUS_CHANGE,"KEY_RESULT",krId,"KR cerrado con ciclo",kr,Map.of("status","CLOSED","cycleClosureId",closure));
        }
        jdbc.update("UPDATE strategic_cycle SET status='CLOSED',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",id);var after=closure(id);audit.record(AuditAction.STATUS_CHANGE,"STRATEGIC_CYCLE",id,"Ciclo cerrado con retrospectiva",before,after);return after;
    }
}
